mapper.select:
SELECT r.report_sq as reportSq, CASE WHEN r.board_sq IS NOT NULL THEN CONCAT('[게시글] ', COALESCE((SELECT board_ttl FROM TBL_BOARD_M WHERE board_sq = r.board_sq), '제목없음')) WHEN r.answer_sq IS NOT NULL THEN CONCAT('[답변] ', COALESCE((SELECT answer_ttl FROM TBL_BOARD_ANSWER_S WHERE answer_sq = r.answer_sq), '제목없음')) WHEN r.comment_sq IS NOT NULL THEN '[댓글] 댓글 신고' WHEN r.reply_comment_sq IS NOT NULL THEN '[대댓글] 대댓글 신고' ELSE '알 수 없음' END as reportTitle, u.user_id as reporterUserId, r.created_at_dtm as createdAtDtm, r.report_reason_txt as reportReasonTxt, r.report_type_cd as reportTypeCd, COALESCE( (SELECT report_status FROM TBL_REPORT_H WHERE report_sq = r.report_sq ORDER BY created_at_dtm DESC LIMIT 1), 'R' ) as status FROM TBL_REPORT_S r JOIN TBL_USER_M u ON r.user_sq = u.user_sq
AND u.user_id LIKE CONCAT('%', #{searchQuery}, '%')
AND DATE(r.created_at_dtm) = #{reportDate}
AND r.report_reason_txt = #{reportReason}
AND COALESCE( (SELECT report_status FROM TBL_REPORT_H WHERE report_sq = r.report_sq ORDER BY created_at_dtm DESC LIMIT 1), 'R' ) = #{status}
ORDER BY r.created_at_dtm DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM TBL_REPORT_S r
JOIN TBL_USER_M u ON r.user_sq = u.user_sq


        AND u.user_id LIKE CONCAT('%', #{searchQuery}, '%')


        AND DATE(r.created_at_dtm) = #{reportDate}


        AND r.report_reason_txt = #{reportReason}


        AND COALESCE(
            (SELECT report_status FROM TBL_REPORT_H WHERE report_sq = r.report_sq ORDER BY created_at_dtm DESC LIMIT 1), 
            'R'
        ) = #{status}
